{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "title": "agent.completions.message.ImageUrl",
  "description": "An image URL for multimodal input.",
  "type": "object",
  "properties": {
    "url": {
      "description": "The URL of the image (can be a data URL or HTTP URL).",
      "type": "string"
    },
    "detail": {
      "description": "The detail level for image processing.",
      "anyOf": [
        {
          "$ref": "agent.completions.message.ImageUrlDetail"
        },
        {
          "type": "null"
        }
      ]
    }
  },
  "required": [
    "url"
  ]
}

{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "title": "functions.expression.InputValue",
  "description": "A concrete input value (post-compilation).\n\nRepresents any JSON-like value that can be passed to a Function,\nincluding rich content types (images, audio, video, files).",
  "anyOf": [
    {
      "description": "Rich content (image, audio, video, file).",
      "$ref": "agent.completions.message.RichContentPart"
    },
    {
      "description": "An object with string keys.",
      "type": "object",
      "additionalProperties": {
        "$ref": "#"
      }
    },
    {
      "description": "An array of values.",
      "type": "array",
      "items": {
        "$ref": "#"
      }
    },
    {
      "description": "A string value.",
      "type": "string"
    },
    {
      "description": "An integer value.",
      "type": "integer",
      "format": "int64"
    },
    {
      "description": "A floating-point number.",
      "type": "number",
      "format": "double"
    },
    {
      "description": "A boolean value.",
      "type": "boolean"
    }
  ]
}

{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "title": "functions.expression.IntegerInputSchema",
  "description": "Schema for an integer input.",
  "type": "object",
  "properties": {
    "type": {
      "$ref": "functions.expression.IntegerInputSchemaType"
    },
    "description": {
      "description": "Human-readable description of the integer.",
      "type": [
        "string",
        "null"
      ]
    },
    "minimum": {
      "description": "Minimum allowed value (inclusive).",
      "type": [
        "integer",
        "null"
      ],
      "format": "int64"
    },
    "maximum": {
      "description": "Maximum allowed value (inclusive).",
      "type": [
        "integer",
        "null"
      ],
      "format": "int64"
    }
  },
  "required": [
    "type"
  ]
}

{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "title": "functions.expression.ArrayInputSchema",
  "description": "Schema for an array input.",
  "type": "object",
  "properties": {
    "type": {
      "$ref": "functions.expression.ArrayInputSchemaType"
    },
    "description": {
      "description": "Human-readable description of the array.",
      "type": [
        "string",
        "null"
      ]
    },
    "minItems": {
      "description": "Minimum number of items required.",
      "type": [
        "integer",
        "null"
      ],
      "format": "uint64",
      "minimum": 0
    },
    "maxItems": {
      "description": "Maximum number of items allowed.",
      "type": [
        "integer",
        "null"
      ],
      "format": "uint64",
      "minimum": 0
    },
    "items": {
      "description": "Schema for each item in the array.",
      "$ref": "functions.expression.InputSchema"
    }
  },
  "required": [
    "type",
    "items"
  ]
}

{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "title": "functions.expression.ImageInputSchema",
  "description": "Schema for an image input (URL or base64-encoded).",
  "type": "object",
  "properties": {
    "type": {
      "$ref": "functions.expression.ImageInputSchemaType"
    },
    "description": {
      "description": "Human-readable description of the expected image.",
      "type": [
        "string",
        "null"
      ]
    }
  },
  "required": [
    "type"
  ]
}

{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "title": "functions.expression.ObjectInputSchema",
  "description": "Schema for an object input with named properties.",
  "type": "object",
  "properties": {
    "type": {
      "$ref": "functions.expression.ObjectInputSchemaType"
    },
    "description": {
      "description": "Human-readable description of the object.",
      "type": [
        "string",
        "null"
      ]
    },
    "properties": {
      "description": "Schema for each property in the object.",
      "type": "object",
      "additionalProperties": {
        "$ref": "functions.expression.InputSchema"
      }
    },
    "required": {
      "description": "List of property names that must be present.",
      "type": [
        "array",
        "null"
      ],
      "items": {
        "type": "string"
      }
    }
  },
  "required": [
    "type",
    "properties"
  ]
}
